package io.github.diodeme.ji.remote;

/** Signed private Host bundle identity selected after remote OS/CPU discovery. */
public record BundleManifest(
        String version, String os, String architecture, String archiveSha256,
        String signatureAlgorithm, String signature) {
    public BundleManifest {
        if (blank(version) || blank(os) || blank(architecture) || blank(archiveSha256)
                || blank(signatureAlgorithm) || blank(signature)) {
            throw new IllegalArgumentException("bundle manifest fields must not be blank");
        }
        if (!"Ed25519".equals(signatureAlgorithm)) {
            throw new IllegalArgumentException("unsupported bundle signature algorithm");
        }
    }

    private static boolean blank(String value) { return value == null || value.isBlank(); }
}

after.content:
    return true;
}

private static boolean validSha256(String value) {
    return value != null && value.matches("[0-9a-f]{64}");
}
